from datetime import time

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if isinstance(value, time):
        return value.strftime('%H:%M:%S')
    return None

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    return list(self._keys.keys())

class BoltProtocol:
    @classmethod
    def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError("Protocol version must be passed in a tuple")

        handlers = {
            (3, 0): BoltProtocolHandlerV30,
            (3, 1): BoltProtocolHandlerV31,
            (4, 0): BoltProtocolHandlerV40,
            (4, 1): BoltProtocolHandlerV41,
        }

        if protocol_version is None:
            return handlers
        else:
            return {protocol_version: handlers.get(protocol_version, None)}

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._data.index(key)
    except ValueError:
        raise KeyError(f"Key '{key}' not found in the data")

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not keys:
        return list(self._items.values())

    results = []
    for key in keys:
        if isinstance(key, int):
            if key < len(self._items):
                results.append(self._items[key])
        elif isinstance(key, str):
            if key in self._items:
                results.append(self._items[key])
        else:
            raise TypeError("Invalid key type. Expected int or str, got {}".format(type(key).__name__))

    return results

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    result = {}
    if not keys:
        for key, value in self._record.items():
            result[key] = value
    else:
        for key in keys:
            if isinstance(key, int):
                if key < 0 or key >= len(self._record):
                    raise IndexError("Out-of-bounds index specified")
                result[self._record.keys()[key]] = self._record.values()[key]
            else:
                result[key] = self._record.get(key, None)
    return result

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    return self.unpack('>H', 2)

def round_half_to_even(n):
    """
    Round half to even (bankers' rounding).

    :param n: The number to round.
    :return: The rounded number.
    """
    if n % 1 == 0.5:
        return int(n) + (1 if n > 0 else -1)
    return round(n)

from typing import Any, Dict, Tuple
from dataclasses import dataclass, field
from collections import namedtuple

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """

    @dataclass
    class Point:
        __slots__ = fields
        __annotations__ = {field: Any for field in fields}
        __init__ = None

        def __post_init__(self):
            for field in fields:
                setattr(self, field, getattr(self, field))

        def __repr__(self):
            return f"{name}({', '.join(f'{field}={getattr(self, field)}' for field in fields)})"

    return Point

import functools
import warnings

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

import re

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    return tuple(map(int, re.split(r'[\._-]+', s)))

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

from functools import wraps, lru_cache

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)
        return lru_cache(maxsize=maxsize, typed=typed)(wrapper)
    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    if not self:
        raise KeyError('dictionary is empty')
    key = next(iter(self))
    value = self[key]
    del self[key]
    return (key, value)

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    return self.__getitem__(key, default)

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(method):
        if lock is None:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    with lock(self):
                        return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    with lock(self):
                        c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, method)
    return decorator

