def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    from collections import defaultdict

    # Create a graph to represent the inheritance relationships
    graph = defaultdict(list)
    for cls in classes:
        for base in cls.__bases__:
            graph[base].append(cls)

    # Function to perform a topological sort
    def topologicalSort(v, visited, stack):
        visited.add(v)
        for neighbor in graph[v]:
            if neighbor not in visited:
                topologicalSort(neighbor, visited, stack)
        stack.append(v)

    # Perform topological sort starting from the base classes
    visited = set()
    stack = []
    for cls in classes:
        if cls not in visited:
            topologicalSort(cls, visited, stack)

    # Reconstruct the minimal bases list from the stack
    minimal = []
    while stack:
        cls = stack.pop()
        if all(base not in minimal for base in cls.__bases__):
            minimal.append(cls)

    return minimal

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    descriptions = {}
    for attr_name in dir(self):
        if not attr_name.startswith('_'):
            attr = getattr(self, attr_name)
            if callable(attr) or not isinstance(attr, property):
                if all or attr.__doc__:
                    descriptions[attr_name] = attr.__doc__
    return descriptions

