def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for item in inventory:
        if item['version'] <= version:
            logical_path = item['logical_path']
            content_file = item['content_file']
            if logical_path not in logical_path_map:
                logical_path_map[logical_path] = set()
            logical_path_map[logical_path].add(content_file)
    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    if 'files' not in fixity:
        raise ValueError("Fixity block must contain a 'files' key")

    if not isinstance(fixity['files'], list):
        raise ValueError("Fixity block 'files' key must be a list")

    for file_info in fixity['files']:
        if not isinstance(file_info, dict):
            raise ValueError("Each file info in fixity block must be a dictionary")

        if 'path' not in file_info:
            raise ValueError("Each file info must contain a 'path' key")

        if 'hash' not in file_info:
            raise ValueError("Each file info must contain a 'hash' key")

        if file_info['path'] not in manifest_files:
            raise ValueError(f"File '{file_info['path']}' referenced in fixity block is not in the manifest")

