def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def apply_absorption(expr):
        if isinstance(expr, tuple) and len(expr) == 3 and expr[0] in ('&', '|'):
            op, a, b = expr
            if op == '&':
                if a == b:
                    return a
                if isinstance(b, tuple) and b[0] == '|':
                    if b[1] == a or b[2] == a:
                        return a
            elif op == '|':
                if a == b:
                    return a
                if isinstance(b, tuple) and b[0] == '&':
                    if b[1] == a or b[2] == a:
                        return a
        return expr

    def apply_negative_absorption(expr):
        if isinstance(expr, tuple) and len(expr) == 3 and expr[0] in ('&', '|'):
            op, a, b = expr
            if op == '&':
                if isinstance(b, tuple) and b[0] == '|':
                    if b[1] == a:
                        return b[2]
                    if b[2] == a:
                        return b[1]
            elif op == '|':
                if isinstance(b, tuple) and b[0] == '&':
                    if b[1] == a:
                        return b[2]
                    if b[2] == a:
                        return b[1]
        return expr

    new_args = []
    for arg in args:
        new_arg = apply_absorption(arg)
        new_arg = apply_negative_absorption(new_arg)
        new_args.append(new_arg)

    return new_args

